body.script:
document.addEventListener('DOMContentLoaded', function() {
    let newSelections = [];

    // Click vào ô ca
    document.querySelectorAll('.shift-cell').forEach(cell => {
        cell.addEventListener('click', function() {
            const date = this.dataset.date;
            const shiftId = this.dataset.shiftId;
            const isRegistered = this.dataset.registered === 'true';

            if (isRegistered) {
                // Nếu đã đăng ký, hỏi có muốn hủy không
                if (confirm('Bạn muốn hủy đăng ký ca này?')) {
                    removeRegistration(date, shiftId, this);
                }
            } else {
                // Toggle chọn
                this.classList.toggle('selected');

                const key = date + '_' + shiftId;
                const index = newSelections.findIndex(s => s.date === date && s.shift_id === shiftId);

                if (index > -1) {
                    newSelections.splice(index, 1);
                } else {
                    newSelections.push({date: date, shift_id: shiftId});
                }

                updateIcon(this);
                updateCount();
            }
        });
    });

    function updateIcon(cell) {
        const icon = cell.querySelector('i');
        if (cell.classList.contains('selected')) {
            icon.className = 'fa fa-check-square';
        } else if (cell.dataset.registered === 'true') {
            icon.className = 'fa fa-check-circle';
        } else {
            icon.className = 'fa fa-circle-o';
        }
    }

    function updateCount() {
        document.getElementById('selectedCount').textContent = newSelections.length;
    }

    // Lưu đăng ký
    document.getElementById('btnSaveRegistration').addEventListener('click', function() {
        if (newSelections.length === 0) {
            alert('Vui lòng chọn ít nhất một ca!');
            return;
        }

        this.disabled = true;
        this.innerHTML = ' Đang lưu...';

        fetch('/shift-registration/save', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {selections: newSelections}
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result && data.result.success) {
                alert(data.result.message);
                location.reload();
            } else {
                alert('Lỗi: ' + (data.result ? data.result.message : 'Không xác định'));
                this.disabled = false;
                this.innerHTML = ' Lưu đăng ký';
            }
        })
        .catch(error => {
            alert('Lỗi kết nối: ' + error);
            this.disabled = false;
            this.innerHTML = ' Lưu đăng ký';
        });
    });

    // Hủy đăng ký
    function removeRegistration(date, shiftId, cell) {
        fetch('/shift-registration/remove', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {date: date, shift_id: shiftId}
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result && data.result.success) {
                cell.classList.remove('registered');
                cell.dataset.registered = 'false';
                cell.querySelector('i').className = 'fa fa-circle-o';
            } else {
                alert('Lỗi: ' + (data.result ? data.result.message : 'Không xác định'));
            }
        });
    }
});
